```python
import argparse

def celsius_to_fahrenheit(celsius):
    return (celsius * 9/5) + 32

def celsius_to_kelvin(celsius):
    return celsius + 273.15

def fahrenheit_to_celsius(fahrenheit):
    return (fahrenheit - 32) * 5/9

def fahrenheit_to_kelvin(fahrenheit):
    return (fahrenheit - 32) * 5/9 + 273.15

def kelvin_to_celsius(kelvin):
    return kelvin - 273.15

def kelvin_to_fahrenheit(kelvin):
    return (kelvin - 273.15) * 9/5 + 32

def main():
    parser = argparse.ArgumentParser(description="Convert temperatures between Celsius, Fahrenheit, and Kelvin.")
    parser.add_argument("value", type=float, help="The temperature value to convert.")
    parser.add_argument("--from", dest="from_unit", required=True, choices=["celsius", "fahrenheit", "kelvin"], help="The unit to convert from.")
    parser.add_argument("--to", dest="to_unit", required=True, choices=["celsius", "fahrenheit", "kelvin"], help="The unit to convert to.")
    args = parser.parse_args()

    value = args.value
    from_unit = args.from_unit
    to_unit = args.to

    if from_unit == "celsius":
        if to_unit == "fahrenheit":
            result = celsius_to_fahrenheit(value)
        elif to_unit == "kelvin":
            result = celsius_to_kelvin(value)
        else:
            result = value
    elif from_unit == "fahrenheit":
        if to_unit == "celsius":
            result = fahrenheit_to_celsius(value)
        elif to_unit == "kelvin":
            result = fahrenheit_to_kelvin(value)
        else:
            result = value
    elif from_unit == "kelvin":
        if to_unit == "celsius":
            result = kelvin_to_celsius(value)
        elif to_unit == "fahrenheit":
            result = kelvin_to_fahrenheit(value)
        else:
            result = value

    print(f"{value} {from_unit} is equal to {result} {to_unit}.")

if __name__ == "__main__":
    main()
```

To use this tool, save it as `temperature_converter.py` and run it from the command line with the following syntax:

```
python temperature_converter.py <value> --from <unit> --to <unit>
```

Replace `<value>` with the temperature value, `<unit>` with the unit to convert from (e.g., `celsius`), and `<unit>` with the unit to convert to (e.g., `fahrenheit`).

